// Build the single gemini-3.5-transcribe request. Diarization is ON here;
// the >30-min fallback (no diarization) lives in "Build Non-Diarized Retry
// Request", wired to this call's error output.
const fileUri = $input.first().json.file.uri;
const vocabulary = $('Get Vocabulary').first().json.phrases;

const requestBody = {
  model: "gemini-3.5-transcribe",
  // NOTE: the exact envelope key for the audio input on POST /v1beta/interactions
  // (here: input.audio) follows the Files API convention used elsewhere in this
  // template; confirm the field name against the live Interactions API docs
  // when available.
  input: {
    audio: {
      file_uri: fileUri,
      mime_type: "audio/mp4"
    }
  },
  language_codes: ["ko-KR"],
  mode: {
    diarization_mode: "speaker"
  },
  custom_vocabulary: vocabulary
};

return [{ json: { requestBody: JSON.stringify(requestBody) } }];

// >30-min fallback: gemini-3.5-transcribe rejects diarization above the
// 30-minute limit (spec section 4.1). Retry the SAME audio once with
// diarization simply omitted -- everything else (vocabulary, language)
// stays the same. "Build Webhook Payload" detects this path ran and sets
// diarized: false accordingly.
const fileUri = $('Upload File to Gemini').item.json.file.uri;
const vocabulary = $('Get Vocabulary').first().json.phrases;

const requestBody = {
  model: "gemini-3.5-transcribe",
  input: {
    audio: {
      file_uri: fileUri,
      mime_type: "audio/mp4"
    }
  },
  language_codes: ["ko-KR"],
  custom_vocabulary: vocabulary
};

return [{ json: { requestBody: JSON.stringify(requestBody) } }];

// TODO(BJJ-231): confirm gemini-3.5-transcribe response shape against the
// live API. The Interactions API response schema for gemini-3.5-transcribe
// is not confirmed anywhere in this repo, and this environment has no
// network access to check it directly. This parser tries the plausible
// documented candidate shapes in order and THROWS when none match, so an
// operator sees a red n8n execution instead of a malformed webhook payload
// silently reaching the backend.
function parseTranscriptRaw(response) {
  // Candidate 1: interaction.output_text -- a serialized diarized transcript
  // (JSON array of {speaker, text}-shaped turns) as a string.
  if (response && response.interaction && typeof response.interaction.output_text === "string") {
    const parsed = JSON.parse(response.interaction.output_text);
    if (Array.isArray(parsed)) {
      return parsed.map((turn) => ({
        speaker: String(turn.speaker !== undefined ? turn.speaker : (turn.speaker_label !== undefined ? turn.speaker_label : "")),
        text: String(turn.text !== undefined ? turn.text : "")
      }));
    }
  }

  // Candidate 2: top-level output_text, same shape, no interaction wrapper.
  if (response && typeof response.output_text === "string") {
    const parsed = JSON.parse(response.output_text);
    if (Array.isArray(parsed)) {
      return parsed.map((turn) => ({
        speaker: String(turn.speaker !== undefined ? turn.speaker : (turn.speaker_label !== undefined ? turn.speaker_label : "")),
        text: String(turn.text !== undefined ? turn.text : "")
      }));
    }
  }

  // Candidate 3: a segments/words array with a per-segment speaker label --
  // the common ASR diarization shape (interaction.output.segments[] or
  // response.segments[]).
  const segments = (response && response.interaction && response.interaction.output && response.interaction.output.segments)
    || (response && response.segments);
  if (Array.isArray(segments) && segments.length > 0) {
    return segments.map((segment) => ({
      speaker: String(segment.speaker !== undefined ? segment.speaker : (segment.speaker_label !== undefined ? segment.speaker_label : (segment.speakerId !== undefined ? segment.speakerId : ""))),
      text: String(segment.text !== undefined ? segment.text : (segment.transcript !== undefined ? segment.transcript : ""))
    }));
  }

  throw new Error(
    "gemini-3.5-transcribe response did not match any known shape " +
    "(interaction.output_text / output_text / segments). Update " +
    "parseTranscriptRaw against the live API response -- see TODO(BJJ-231)."
  );
}

const trigger = $('Google Drive Trigger').item.json;
const vocabularyVersion = $('Get Vocabulary').first().json.version;

// The >30-min fallback fired iff its retry node ran in this execution.
// This node is reachable from BOTH the primary success output AND the
// non-diarized retry, so "cannot tell whether the retry ran" must never
// silently default to diarized: true -- that would label guessed speaker
// attribution as real. Fail loud instead. (The backend also cross-checks:
// a payload claiming diarized with <2 distinct speaker labels is treated
// as non-diarized.)
let diarized;
try {
  const retryExecuted = $('Gemini Transcribe Audio (Non-Diarized Retry)').isExecuted;
  if (typeof retryExecuted !== "boolean") {
    throw new Error("isExecuted returned " + typeof retryExecuted);
  }
  diarized = retryExecuted === false;
} catch (e) {
  throw new Error(
    "Cannot determine whether the non-diarized retry executed (" + e.message + "). " +
    "This n8n version may not support isExecuted -- fix the diarized detection " +
    "before activating. See docs/n8n/README.md."
  );
}

const transcriptRaw = parseTranscriptRaw($json);

return [{
  json: {
    driveFileId: trigger.id,
    fileName: trigger.name,
    recordedAt: trigger.createdTime || undefined,
    sttModel: "gemini-3.5-transcribe",
    diarized: diarized,
    vocabularyVersion: vocabularyVersion,
    transcriptRaw: transcriptRaw
  }
}];
